// Minimal in-browser classifier skeleton
function predict(text) {
  const t = text.toLowerCase();
  let score = 0;

  // Rule-based sentiment cues
  const positiveWords = ['awesome', 'great', 'excellent', 'good', 'amazing'];
  const negativeWords = ['bad', 'terrible', 'awful', 'poor', 'worst'];

  positiveWords.forEach(w => { if (t.includes(w)) score += 1; });
  negativeWords.forEach(w => { if (t.includes(w)) score -= 1; });

  // Determine sentiment
  if (score > 0) return 'positive';
  if (score < 0) return 'negative';
  return 'neutral';
}
```

